      "content": "{\n  \"schema_version\": \"domainspec.cross-generator-execution-definition/v1-candidate\",\n  \"status\": \"candidate\",\n  \"authority_effect\": \"none\",\n  \"meaning\": \"Own the private Rule-to-Policy native experiment from exact registered controls and plan through compilation, independent module audits, actual instrumented execution and retained currentness.\",\n  \"inputs\": \"Exact pinned definition, registered reconciled plan and registered Policy interoperability controls with equal plan identity. Only ready Policy closures enter execution. Empty ready coverage rejects; unavailable families and uncovered runtime edges remain explicit.\",\n  \"source_custody\": \"Use captured immutable plan artifacts, not later authoring-directory reads. Verify their bytes against the independently source-derived controls. Copy only selected Rule and Policy closure into a fresh owned workspace; never copy or load Policy targets.\",\n  \"native_surface\": \"Independently parse every source TypeScript and emitted CommonJS module using the selected native TypeScript API. Compare literal import paths and named exports with source-derived bindings; reject dynamic, nested, aliased require, reexports, unexpected exports and external module references. Check listed ambient syntax restrictions. These bounded syntactic checks are not universal purity or sandbox proof.\",\n  \"tools\": \"Require Node 26.8.1 and installed TypeScript 7.0.2. Bind the Node executable, complete TypeScript package tree and complete selected platform compiler package tree including native executable. Generated closure uses no ambient type packages. Reinventory tools and owned source/native/config/script/input/output bytes before and after children and at final receipt assertion. Symlinks, extras, omissions, nonregular files and changed bytes reject. This is before/after custody, not atomic filesystem isolation against concurrent privileged writers.\",\n  \"execution\": \"Strict CommonJS compilation in the owned workspace. Complete source/native audits precede permission-restricted Node behavior. Use the existing trace observer with no expected values or traces in its payload. Compare all actual observations with registered source-derived controls. No passing prefix after error, capacity exhaustion or drift.\",\n  \"receipt\": \"Deeply frozen process-registered result binds controls, plan, definition, all artifact and tool hashes and exact audit/behavior observations. Assertion rechecks retained custody. Clones cannot revive receipts. Workspace remains owned by this run and retained for its caller to inspect and clean up; failed runs expose their exact workspace path without deleting caller files.\",\n  \"limits\": {\n    \"modules\": 8192,\n    \"files\": 16384,\n    \"file_bytes\": 268435456,\n    \"aggregate_tool_bytes\": 536870912,\n    \"aggregate_native_bytes\": 67108864,\n    \"input_bytes\": 16777216,\n    \"output_bytes\": 16777216,\n    \"child_timeout_ms\": 60000,\n    \"ast_visits_per_module\": 1000000,\n    \"ast_depth\": 512\n  },\n  \"forbidden_forms\": [\n    \"ImportKeyword\",\n    \"ImportEqualsDeclaration\",\n    \"ExportAssignment\",\n    \"WithStatement\",\n    \"DebuggerStatement\"\n  ],\n  \"forbidden_identifiers\": [\n    \"process\",\n    \"globalThis\",\n    \"global\",\n    \"window\",\n    \"document\",\n    \"eval\",\n    \"Function\",\n    \"AsyncFunction\",\n    \"GeneratorFunction\",\n    \"WebAssembly\",\n    \"fetch\",\n    \"XMLHttpRequest\",\n    \"console\",\n    \"setTimeout\",\n    \"setInterval\",\n    \"setImmediate\",\n    \"queueMicrotask\",\n    \"Worker\",\n    \"SharedArrayBuffer\",\n    \"Atomics\",\n    \"module\",\n    \"__dirname\",\n    \"__filename\"\n  ],\n  \"claim_ceiling\": \"Finite private instrumented Rule-to-Policy evidence and bounded static module audit. Not uninstrumented equivalence, whole-project or cross-generator completion, public capsule integration, production effects, default change, installation, admission or release.\"\n}\n",
