      "content": "{\n  \"schema_version\": \"domainspec.cross-generator-factory-execution-definition/v1-candidate\",\n  \"status\": \"candidate\",\n  \"authority_effect\": \"none\",\n  \"meaning\": \"Own finite private factory-to-Rule execution from independently source-derived module surfaces through native audit, strict compilation, original instrumented behavior and retained currentness.\",\n  \"inputs\": \"Registered checked graph, reconciled plan, complete boundary inventory and registered factory interoperability controls with equal identities; exact definition bytes. Empty ready coverage rejects.\",\n  \"source_surface\": {\n    \"derivation\": \"Derive factory, Rule, named Entity/Value Object, plain Enum component/definition/runtime and payload-sum paths and named value/type exports from decoded source contracts, checked selected field bindings and configured roles. Reconstruct each import occurrence, including repeated fields and type-only references, without parsing generated text for expected answers. Compare expected closure with static inventory and bind captured artifact bytes.\",\n    \"roles\": \"Entity/Value Object modules export Fields and Snapshot types plus create<Name>Factory, <Name>ValueComponent and <Name>FieldBindings values. Rules export rule<Name>. Payload Enum modules export Input/Case types and ValueComponent; plain Enum components export Case and ValueComponent and import their definition. Plain definitions export the source name as both type and value and import defineEnum and EnumValue. Shared Enum runtime has exact pinned source and exports defineEnum/composeEnum values and EnumValue type.\",\n    \"closure\": \"Only ready root closures execute. Retain owned-value, Enum and type-only edges in the denominator without calling them factory-to-Rule invocation proof. Type-only targets may participate in compilation/auditing without being loaded by native behavior.\"\n  },\n  \"native_surface\": \"Independently parse original TypeScript and emitted CommonJS with selected TypeScript API. Check every static named import occurrence, type-only erasure, complete type/value exports and bounded ambient syntax restrictions. Reject dynamic/nested/aliased require, namespace escape, export reassignment or extra binding, runtime reexports, external imports and unknown CommonJS export forms. Explicitly permit required compiler-generated export initialization and statically named original factory/owned-component initialization; this is bounded syntax assurance, not universal purity.\",\n  \"source_custody\": \"Use captured immutable artifacts and independently reconstructed surfaces, not mutable authoring reads. Fresh owned workspace retains exact source/native/config/script/input/output and complete Node/TypeScript/platform fingerprints, checked before/after child execution and on receipt assertion. Changed, missing, extra, symbolic or nonregular selected files reject; not atomic isolation against privileged concurrent writers.\",\n  \"execution\": \"Use existing source-derived factory lifecycle cases and original Rule instrumentation. Only requested factory create/reconstruct/transition/extend calls count; setup/previous/copy/foreign construction stays separate. Exclude expected answers from native input. Complete audits precede restricted native behavior; compare all observations. Preserve prior family definitions and native behavior.\",\n  \"tools\": \"Node 26.8.1, TypeScript 7.0.2, same retained private execution limits and permission-restricted CommonJS lane. No ambient type packages.\",\n  \"receipt\": \"Registered immutable family-specific result binds definition, source surface controls, original behavioral controls, graph/plan and exact audit/behavior/artifact/tool evidence. Cloned or stale receipts reject; failures retain their owned workspace for inspection.\",\n  \"limits\": {\n    \"modules\": 8192,\n    \"files\": 16384,\n    \"file_bytes\": 268435456,\n    \"aggregate_tool_bytes\": 536870912,\n    \"aggregate_native_bytes\": 67108864,\n    \"input_bytes\": 16777216,\n    \"output_bytes\": 16777216,\n    \"child_timeout_ms\": 60000,\n    \"ast_visits_per_module\": 1000000,\n    \"ast_depth\": 512\n  },\n  \"forbidden_forms\": [\n    \"ImportKeyword\",\n    \"ImportEqualsDeclaration\",\n    \"ExportAssignment\",\n    \"WithStatement\",\n    \"DebuggerStatement\"\n  ],\n  \"forbidden_identifiers\": [\n    \"process\",\n    \"globalThis\",\n    \"global\",\n    \"window\",\n    \"document\",\n    \"eval\",\n    \"Function\",\n    \"AsyncFunction\",\n    \"GeneratorFunction\",\n    \"WebAssembly\",\n    \"fetch\",\n    \"XMLHttpRequest\",\n    \"console\",\n    \"setTimeout\",\n    \"setInterval\",\n    \"setImmediate\",\n    \"queueMicrotask\",\n    \"Worker\",\n    \"SharedArrayBuffer\",\n    \"Atomics\",\n    \"module\",\n    \"__dirname\",\n    \"__filename\"\n  ],\n  \"claim_ceiling\": \"Finite private instrumented factory-to-Rule evidence with independent surface audit and retained custody only. No universal purity, uninstrumented equivalence, public cross-generator completion, default change, release or authority.\"\n}\n",
